    if (!GONE_AFTER_RETENTION.has(i.status)) return true
    const closed = Date.parse(i.closedAt)
    return !Number.isFinite(closed) || now - closed <= CLOSED_RETENTION_MS
  })
  return kept.length === items.length ? items : kept
}

